"""Runtime support for vecDSL programs generated for LanceDB (embedded, open source). Generated by vecDSL 7. Do not edit.

The generator builds every table schema, where string, index parameter set and write plan; this module only calls the
lancedb SDK, converts records to the declared Arrow schema and reports results in one form for every host language.
"""

from __future__ import annotations

import json
import math
import os
import random
import re
from datetime import date, datetime, timedelta, timezone
from importlib.metadata import PackageNotFoundError, version
from typing import Any, NoReturn, Sequence

SDK_PACKAGE = "{{sdk.python.package}}"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"

_DIGITS = 6
_BATCH = 1000


class UnsupportedFeature(NotImplementedError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()

import lancedb  # noqa: E402
import numpy as np  # noqa: E402
import pyarrow as pa  # noqa: E402
from lancedb.index import FTS, BTree, Bitmap, HnswPq, HnswSq, IvfFlat, IvfPq, IvfRq, LabelList  # noqa: E402
from lancedb.query import FullTextOperator, MatchQuery, MultiMatchQuery, PhraseQuery  # noqa: E402


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


# ---------------------------------------------------------------- where strings


def sql(template: str, values: dict[str, Any]) -> str:
    """A generated where template with each {name} replaced by the SQL literal of a program parameter."""
    def fill(match: re.Match[str]) -> str:
        value = values[match.group(1)]
        if match.group(2):
            if not isinstance(value, (list, tuple)) or not value:
                raise ValueError(f"in and not_in need a non-empty list, got {value!r}")
            return "(" + ", ".join(literal(item) for item in value) + ")"
        return literal(value)
    return re.sub(r"\{([A-Za-z0-9_]+)(:list)?\}", fill, template)


def literal(value: Any) -> str:
    """The SQL literal of a value: strings in single quotes with quotes doubled, lists as array literals."""
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "TRUE" if value else "FALSE"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        if not math.isfinite(value):
            raise ValueError(f"cannot use {value!r} in a filter")
        return _number(value)
    if isinstance(value, str):
        return "'" + value.replace("'", "''") + "'"
    if isinstance(value, (list, tuple)):
        return "[" + ", ".join(literal(item) for item in value) + "]"
    raise TypeError(f"cannot use {value!r} in a filter")


def _number(value: float) -> str:
    if value.is_integer() and abs(value) < 1e15:
        return str(int(value))
    return repr(value)


# ---------------------------------------------------------------- connection


class Client:
    """The storage URI of the program's database and one connection per logical database (a sub-directory)."""

    def __init__(self, uri: str, interval: float) -> None:
        self.uri = uri
        self.interval = interval
        self._connections: dict[str, Any] = {}

    def db(self, database: str | None = None) -> Any:
        name = database or ""
        if name not in self._connections:
            target = self.uri if not name else self.uri.rstrip("/\\") + "/" + name
            if "://" not in target:
                os.makedirs(target, exist_ok=True)
            self._connections[name] = lancedb.connect(target, read_consistency_interval=timedelta(seconds=self.interval))
        return self._connections[name]

    def table(self, table: dict[str, Any]) -> Any:
        return self.db(table.get("database")).open_table(table["name"])

    def forget(self, database: str) -> None:
        connection = self._connections.pop(database, None)
        if connection is not None:
            connection.close()

    def close(self) -> None:
        for connection in self._connections.values():
            connection.close()
        self._connections.clear()


def connect(uri: str, interval: float = 0.0) -> Client:
    return Client(uri, interval)


def create_database(client: Client, database: str) -> None:
    """A logical database is a sub-directory of the storage URI, created when it is first used."""
    client.db(database)


def require_table(client: Client, table: dict[str, Any]) -> None:
    if not has_table(client, table):
        raise KeyError(f"table {table['name']} does not exist")


def load_table(client: Client, table: dict[str, Any]) -> None:
    """Loads the table's indexes into the cache (prewarm_index); prewarm_data is remote-only in LanceDB OSS
    (rust/lancedb/src/table.rs), and an index that covers no rows yet (created on an empty table) has no files to load."""
    handle = client.table(table)
    for index in handle.list_indices():
        if handle.index_stats(index.name).num_indexed_rows > 0:
            handle.prewarm_index(index.name)


def has_table(client: Client, table: dict[str, Any]) -> bool:
    return table["name"] in _names(client.db(table.get("database")))


def _names(connection: Any) -> list[str]:
    names: list[str] = []
    token = None
    while True:
        page = connection.list_tables(page_token=token)
        names.extend(page.tables)
        token = page.page_token
        if not token:
            return names


# ---------------------------------------------------------------- schema


_SCALARS = {
    "int8": pa.int8(), "int32": pa.int32(), "int64": pa.int64(), "float32": pa.float32(), "float64": pa.float64(),
    "bool": pa.bool_(), "utf8": pa.utf8(), "binary": pa.binary(), "date": pa.date32(), "timestamp": pa.timestamp("us"),
    "timestamptz": pa.timestamp("us", tz="UTC"), "float16": pa.float16(), "uint8": pa.uint8(),
}


def arrow_type(field: dict[str, Any]) -> pa.DataType:
    kind = field["type"]
    if kind in _SCALARS:
        return _SCALARS[kind]
    if kind == "list":
        return pa.list_(arrow_field({"name": "item", **field["element"]}))
    if kind == "struct":
        return pa.struct([arrow_field(child) for child in field["fields"]])
    if kind == "vector":
        return pa.list_(pa.field("item", _SCALARS[field["element"]]), int(field["dim"]))
    if kind == "multivector":
        return pa.list_(pa.field("item", pa.list_(pa.field("item", _SCALARS[field["element"]]), int(field["dim"]))))
    raise ValueError(f"unknown field type {kind}")


def arrow_field(field: dict[str, Any]) -> pa.Field:
    metadata = {key: _text(value) for key, value in field.get("metadata", {}).items()}
    return pa.field(field["name"], arrow_type(field), nullable=field.get("nullable", True), metadata=metadata or None)


def arrow_schema(fields: Sequence[dict[str, Any]]) -> pa.Schema:
    return pa.schema([arrow_field(field) for field in fields])


def _convert(value: Any, field: dict[str, Any]) -> Any:
    if value is None:
        return None
    kind = field["type"]
    if kind in ("int8", "int32", "int64", "uint8"):
        if isinstance(value, float) and value.is_integer():
            return int(value)
        return value
    if kind in ("float32", "float64", "float16"):
        return float(value)
    if kind == "date" and isinstance(value, str):
        return date.fromisoformat(value)
    if kind in ("timestamp", "timestamptz") and isinstance(value, str):
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if kind == "timestamptz" and parsed.tzinfo is None:
            parsed = parsed.replace(tzinfo=timezone.utc)
        return parsed
    if kind == "binary" and isinstance(value, str):
        return value.encode("utf-8")
    if kind == "list":
        return [_convert(item, field["element"]) for item in value]
    if kind == "struct":
        return {child["name"]: _convert(value.get(child["name"]), child) for child in field["fields"]}
    if kind == "vector" and "bits" in field:
        return list(value) if len(value) == field["dim"] else pack(value)
    if kind == "vector":
        return [float(x) for x in value]
    if kind == "multivector":
        return [[float(x) for x in vector] for vector in value]
    return value


def _rows(fields: Sequence[dict[str, Any]], rows: Sequence[dict[str, Any]], defaults: dict[str, Any] | None,
          slice: dict[str, Any] | None) -> pa.Table:
    """Records as an Arrow table of the declared schema: defaults for absent fields, slice columns, unknown names rejected."""
    known = {field["name"]: field for field in fields}
    converted = []
    for row in rows:
        unknown = sorted(set(row) - set(known))
        if unknown:
            raise KeyError(f"unknown fields {', '.join(unknown)}")
        record = {**(defaults or {}), **row, **(slice or {})}
        converted.append({name: _convert(record.get(name), field) for name, field in known.items()})
    return pa.Table.from_pylist(converted, schema=arrow_schema(fields))


# ---------------------------------------------------------------- DDL


def create_table(client: Client, table: dict[str, Any], schema: Sequence[dict[str, Any]],
                 indexes: Sequence[dict[str, Any]] = (), exist_ok: bool = False) -> None:
    connection = client.db(table.get("database"))
    if exist_ok and table["name"] in _names(connection):
        return
    handle = connection.create_table(table["name"], schema=arrow_schema(schema))
    for index in indexes:
        _create_index(handle, index)


def drop_table(client: Client, table: dict[str, Any], missing_ok: bool = False) -> None:
    connection = client.db(table.get("database"))
    if missing_ok and table["name"] not in _names(connection):
        return
    connection.drop_table(table["name"])


def drop_database(client: Client, database: str) -> None:
    """Drops every table of the logical database and removes its sub-directory when that is left empty."""
    client.db(database).drop_all_tables()
    client.forget(database)
    folder = client.uri.rstrip("/\\") + "/" + database
    if "://" not in folder and os.path.isdir(folder) and not os.listdir(folder):
        os.rmdir(folder)


def list_databases(client: Client) -> list[str]:
    if "://" in client.uri:
        unsupported("lancedb", "listing logical databases of an object-store URI")
    if not os.path.isdir(client.uri):
        return []
    return sorted(name for name in os.listdir(client.uri)
                  if os.path.isdir(os.path.join(client.uri, name)) and not name.endswith(".lance"))


def _copy(client: Client, table: dict[str, Any], target: dict[str, Any], schema: Sequence[dict[str, Any]],
          indexes: Sequence[dict[str, Any]], version: Any = None) -> Any:
    source = client.table(table)
    if version is not None:
        source.checkout(version)
    data = source.to_arrow()
    handle = client.db(target.get("database")).create_table(target["name"], data=data, schema=arrow_schema(schema))
    for index in indexes:
        _create_index(handle, index)
    return handle


def rename_table(client: Client, table: dict[str, Any], new_name: str, schema: Sequence[dict[str, Any]],
                 indexes: Sequence[dict[str, Any]] = ()) -> None:
    """LanceDB OSS has no rename: copies rows, schema and declared indexes into the new table, then drops the old one."""
    _copy(client, table, {**table, "name": new_name}, schema, indexes)
    client.db(table.get("database")).drop_table(table["name"])


def clone_table(client: Client, table: dict[str, Any], target: str, shallow: bool, schema: Sequence[dict[str, Any]],
                indexes: Sequence[dict[str, Any]] = (), version: Any = None) -> dict[str, Any]:
    """A shallow clone references the source's files at a version or tag; a full clone copies the rows."""
    connection = client.db(table.get("database"))
    if shallow:
        source = client.table(table)
        options: dict[str, Any] = {}
        if isinstance(version, str):
            options["source_tag"] = version
        elif version is not None:
            options["source_version"] = int(version)
        handle = connection.clone_table(target, source.uri, **options)
    else:
        handle = _copy(client, table, {**table, "name": target}, schema, indexes, version)
    return {"cloned_count": handle.count_rows()}


def list_tables(client: Client, database: str | None = None, prefix: str | None = None,
                limit: int | None = None) -> list[str]:
    names = sorted(name for name in _names(client.db(database)) if prefix is None or name.startswith(prefix))
    return names if limit is None else names[:limit]


def add_columns(client: Client, table: dict[str, Any], fields: Sequence[dict[str, Any]],
                values: dict[str, str] | None = None) -> None:
    """New columns: null-filled from their Arrow fields, or computed from generated SQL expressions (defaults),
    which LanceDB marks non-null, so they are made nullable again for later writes that omit them."""
    handle = client.table(table)
    plain = [arrow_field(field) for field in fields if field["name"] not in (values or {})]
    if plain:
        handle.add_columns(plain)
    if values:
        handle.add_columns(dict(values))
        handle.alter_columns(*({"path": name, "nullable": True} for name in values))


def drop_columns(client: Client, table: dict[str, Any], names: Sequence[str]) -> None:
    client.table(table).drop_columns(list(names))


def rename_column(client: Client, table: dict[str, Any], name: str, new_name: str) -> None:
    client.table(table).alter_columns({"path": name, "rename": new_name})


def set_metadata(client: Client, table: dict[str, Any], metadata: dict[str, Any]) -> None:
    """Collection properties live in the metadata of the key column (LanceDB tables have no table-level properties)."""
    client.table(table).update_field_metadata({"path": table["key"], "metadata": {key: _text(value) for key, value in metadata.items()}})


def _text(value: Any) -> str:
    return value if isinstance(value, str) else json.dumps(value)


def _index_config(index: dict[str, Any]) -> Any:
    kind = index["kind"]
    metric = index.get("metric")
    vector = {"distance_type": metric} if metric else {}
    for option in ("num_partitions", "num_sub_vectors", "num_bits", "m", "ef_construction", "sample_rate", "max_iterations"):
        if option in index:
            vector[option] = int(index[option])
    if kind == "btree":
        return BTree()
    if kind == "bitmap":
        return Bitmap()
    if kind == "label_list":
        return LabelList()
    if kind == "fts":
        options = {key: index[key] for key in ("base_tokenizer", "language", "stem", "remove_stop_words", "lower_case",
                                               "ascii_folding", "with_position", "max_token_length", "ngram_min_length",
                                               "ngram_max_length", "prefix_only") if key in index}
        return FTS(**options)
    builders = {"ivf_flat": IvfFlat, "ivf_pq": IvfPq, "ivf_rq": IvfRq, "ivf_hnsw_sq": HnswSq, "ivf_hnsw_pq": HnswPq}
    if kind not in builders:
        raise ValueError(f"unknown index kind {kind}")
    return builders[kind](**vector)


def _create_index(handle: Any, index: dict[str, Any]) -> None:
    handle.create_index(index["column"], config=_index_config(index), replace=True, name=index["name"])


def create_index(client: Client, table: dict[str, Any], index: dict[str, Any]) -> None:
    _create_index(client.table(table), index)


def drop_index(client: Client, table: dict[str, Any], name: str) -> None:
    client.table(table).drop_index(name)


def rebuild_index(client: Client, table: dict[str, Any], index: dict[str, Any]) -> None:
    """Retrains the index over every row: create_index with replace."""
    _create_index(client.table(table), index)


def await_index(client: Client, table: dict[str, Any], name: str, timeout: float = 300.0) -> dict[str, Any]:
    handle = client.table(table)
    handle.wait_for_index([name], timeout=timedelta(seconds=timeout))
    stats = handle.index_stats(name)
    return {"index": name, "indexed_rows": stats.num_indexed_rows, "unindexed_rows": stats.num_unindexed_rows}


def list_indexes(client: Client, table: dict[str, Any], prefix: str | None = None, limit: int | None = None) -> list[str]:
    names = sorted(index.name for index in client.table(table).list_indices()
                   if prefix is None or index.name.startswith(prefix))
    return names if limit is None else names[:limit]


def optimize(client: Client, table: dict[str, Any]) -> None:
    """Compacts small files, removes untagged versions older than seven days (LanceDB's default; tagged versions stay)
    and adds new rows to every index.
    Lance 14.0.2 cannot add rows to a scalar index on a nested column that was created on an empty table (it looks the
    leaf name up as a top-level column, rust/lance/src/index/scalar.rs), so such indexes are rebuilt over the rows first."""
    handle = client.table(table)
    if handle.count_rows() > 0:
        for index in handle.list_indices():
            nested = index.columns[0]
            if index.index_type in _SCALAR and "." in nested and handle.index_stats(index.name).num_indexed_rows == 0:
                handle.create_index(nested, config=_SCALAR[index.index_type](), replace=True, name=index.name)
    handle.optimize()


_SCALAR = {"BTree": BTree, "Bitmap": Bitmap, "LabelList": LabelList}


def describe(client: Client, table: dict[str, Any], stats: bool = False, index_progress: bool = False) -> dict[str, Any]:
    handle = client.table(table)
    result: dict[str, Any] = {"name": table["name"], "fields": [_describe_field(field) for field in handle.schema],
                              "indexes": sorted(index.name for index in handle.list_indices())}
    metadata = handle.schema.field(table["key"]).metadata or {}
    for key, value in sorted(metadata.items()):
        result[key.decode()] = value.decode()
    if stats:
        result["rows"] = handle.count_rows()
        result["version"] = handle.version
    if index_progress:
        progress = {}
        for index in handle.list_indices():
            statistics = handle.index_stats(index.name)
            progress[index.name] = {"indexed_rows": statistics.num_indexed_rows,
                                    "unindexed_rows": statistics.num_unindexed_rows}
        result["index_progress"] = progress
    return result


def _describe_field(field: pa.Field) -> dict[str, Any]:
    return {"name": field.name, "type": str(field.type), "nullable": field.nullable}


# ---------------------------------------------------------------- versions


def create_tag(client: Client, table: dict[str, Any], tag: str | None = None) -> dict[str, Any]:
    """Tags the current version; without a name the tag is v<version>."""
    handle = client.table(table)
    tag = tag or f"v{handle.version}"
    handle.tags.create(tag, handle.version)
    return {"snapshot": tag, "version": handle.version}


def restore_tag(client: Client, table: dict[str, Any], tag: str) -> dict[str, Any]:
    """Checks out the tagged version and commits it as the newest version (time travel, then restore)."""
    handle = client.table(table)
    handle.checkout(tag)
    handle.restore()
    return {"restored_count": handle.count_rows()}


def drop_tag(client: Client, table: dict[str, Any], tag: str) -> None:
    client.table(table).tags.delete(tag)


def list_tags(client: Client, table: dict[str, Any], prefix: str | None = None, limit: int | None = None) -> list[str]:
    names = sorted(name for name in client.table(table).tags.list() if prefix is None or name.startswith(prefix))
    return names if limit is None else names[:limit]


def _read(client: Client, table: dict[str, Any], version: Any = None) -> Any:
    """The table at its latest version, or checked out at a version number or tag (time travel, read only)."""
    handle = client.table(table)
    if version is not None:
        handle.checkout(int(version) if isinstance(version, float) else version)
    return handle


# ---------------------------------------------------------------- writes


def _key_list(table: dict[str, Any], keys: Sequence[Any]) -> str:
    return f"{quote(table['key'])} IN ({', '.join(literal(_key(key)) for key in keys)})"


def _key(value: Any) -> Any:
    if isinstance(value, float) and value.is_integer():
        return int(value)
    return value


def quote(name: str) -> str:
    return ".".join("`" + part.replace("`", "``") + "`" for part in name.split("."))


def insert(client: Client, table: dict[str, Any], schema: Sequence[dict[str, Any]], rows: Sequence[dict[str, Any]],
           on_conflict: str = "error", defaults: dict[str, Any] | None = None,
           slice: dict[str, Any] | None = None, batch_size: int | None = None) -> dict[str, Any]:
    """Inserts records keyed by the primary key: a merge insert that only inserts, after a check for existing keys
    (on-conflict error), or that also updates matches (update, replace); LanceDB itself has no primary-key constraint."""
    handle = client.table(table)
    count = 0
    for start in range(0, len(rows), batch_size or _BATCH):
        batch = list(rows[start:start + (batch_size or _BATCH)])
        keys = [_key(row.get(table["key"])) for row in batch]
        if len(set(map(json.dumps, keys))) != len(keys):
            raise ValueError(f"duplicate keys in one insert into {table['name']}")
        if on_conflict == "error":
            existing = handle.count_rows(_key_list(table, keys))
            if existing:
                raise ValueError(f"{existing} of the keys already exist in {table['name']}")
        data = _rows(schema, batch, defaults, slice)
        builder = handle.merge_insert(table["key"])
        if on_conflict in ("update", "replace"):
            builder = builder.when_matched_update_all()
        result = builder.when_not_matched_insert_all().execute(data)
        count += result.num_inserted_rows + result.num_updated_rows
    return {"insert_count": count}


def upsert(client: Client, table: dict[str, Any], schema: Sequence[dict[str, Any]], rows: Sequence[dict[str, Any]],
           defaults: dict[str, Any] | None = None, slice: dict[str, Any] | None = None,
           batch_size: int | None = None) -> dict[str, Any]:
    handle = client.table(table)
    count = 0
    for start in range(0, len(rows), batch_size or _BATCH):
        data = _rows(schema, rows[start:start + (batch_size or _BATCH)], defaults, slice)
        result = handle.merge_insert(table["key"]).when_matched_update_all().when_not_matched_insert_all().execute(data)
        count += result.num_inserted_rows + result.num_updated_rows
    return {"upsert_count": count}


def read_records(_client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URIs and paths)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    if text.lstrip().startswith("["):
        return json.loads(text)
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, table: dict[str, Any], schema: Sequence[dict[str, Any]], location: str,
                on_conflict: str = "error", defaults: dict[str, Any] | None = None, slice: dict[str, Any] | None = None,
                batch_size: int | None = None) -> dict[str, Any]:
    rows = read_records(client, location)
    if on_conflict == "skip":
        result = insert(client, table, schema, rows, "skip", defaults, slice, batch_size)
    else:
        result = insert(client, table, schema, rows, on_conflict, defaults, slice, batch_size)
    return {"import_count": result["insert_count"]}


def update(client: Client, table: dict[str, Any], where: str, values: dict[str, str]) -> dict[str, Any]:
    """An UPDATE with generated SQL expressions (literals, array_append, array_remove_all) on the rows of a where string."""
    result = client.table(table).update(where=where, values_sql=dict(values))
    return {"update_count": result.rows_updated}


def replace_rows(client: Client, table: dict[str, Any], schema: Sequence[dict[str, Any]], where: str,
                 values: dict[str, Any], defaults: dict[str, Any] | None = None) -> dict[str, Any]:
    """Update mode replace: every matching record is rewritten with the given values and nulls (or defaults) elsewhere;
    vectors and slice columns are kept."""
    handle = client.table(table)
    kept = _kept(table, schema)
    found = handle.search().where(where).select(kept).to_list()
    if not found:
        return {"update_count": 0}
    rows = [{**{name: row.get(name) for name in kept}, **values} for row in found]
    handle.merge_insert(table["key"]).when_matched_update_all().execute(_rows(schema, rows, defaults, None))
    return {"update_count": len(found)}


def _kept(table: dict[str, Any], schema: Sequence[dict[str, Any]]) -> list[str]:
    return [table["key"]] + [field["name"] for field in schema
                             if field["type"] in ("vector", "multivector") or field["name"].startswith("vecdsl_")]


def update_from(client: Client, table: dict[str, Any], schema: Sequence[dict[str, Any]], rows: Sequence[dict[str, Any]],
                where: str | None = None) -> dict[str, Any]:
    """Update from records: a merge insert that updates the matching keys (optionally only rows of a where string)."""
    handle = client.table(table)
    builder = handle.merge_insert(table["key"])
    builder = builder.when_matched_update_all(where=where) if where else builder.when_matched_update_all()
    current = _existing(handle, table, rows)
    data = _rows(schema, [{**current.get(json.dumps(_key(row[table["key"]])), {}), **row} for row in rows], None, None)
    result = builder.execute(data)
    return {"update_count": result.num_updated_rows}


def _existing(handle: Any, table: dict[str, Any], rows: Sequence[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    keys = [_key(row[table["key"]]) for row in rows]
    if not keys:
        return {}
    found = handle.search().where(_key_list(table, keys)).limit(len(keys)).to_list()
    return {json.dumps(_key(row[table["key"]])): {name: value for name, value in row.items() if not name.startswith("_")}
            for row in found}


def patch_rows(client: Client, table: dict[str, Any], schema: Sequence[dict[str, Any]], where: str,
               values: dict[str, Any]) -> dict[str, Any]:
    """Vector, list and struct values: the matching rows are read, changed and written back by a merge insert on the key."""
    handle = client.table(table)
    names = [field["name"] for field in schema]
    found = handle.search().where(where).select(names).limit(handle.count_rows() or 1).to_list()
    if not found:
        return {"update_count": 0}
    rows = [{**{name: row.get(name) for name in names}, **values} for row in found]
    result = handle.merge_insert(table["key"]).when_matched_update_all().execute(_rows(schema, rows, None, None))
    return {"update_count": result.num_updated_rows}


def list_values(client: Client, table: dict[str, Any], column: str, prefix: str | None = None,
                limit: int | None = None) -> list[str]:
    """The distinct values of a slice column (tenants, namespaces, partitions), sorted."""
    handle = client.table(table)
    rows = handle.search().select([column]).limit(handle.count_rows() or 1).to_list()
    values = sorted({row[column] for row in rows if row[column] is not None and (prefix is None or row[column].startswith(prefix))})
    return values if limit is None else values[:limit]


def delete(client: Client, table: dict[str, Any], where: str, limit: int | None = None) -> dict[str, Any]:
    """Deletes the rows of a where string; a limit deletes the first rows in key order (LanceDB's delete has no limit)."""
    handle = client.table(table)
    if limit is not None:
        keys = sorted((row[table["key"]] for row in handle.search().where(where).select([table["key"]]).to_list()),
                      key=_sort_key)[:limit]
        if not keys:
            return {"delete_count": 0}
        where = _key_list(table, keys)
    result = handle.delete(where)
    return {"delete_count": result.num_deleted_rows}


def truncate(client: Client, table: dict[str, Any], where: str = "true") -> dict[str, Any]:
    return delete(client, table, where)


# ---------------------------------------------------------------- reads


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers."""
    if isinstance(value, float):
        if not math.isfinite(value):
            return None
        rounded = round(value, _DIGITS)
        if rounded == 0:
            return 0
        return int(rounded) if rounded.is_integer() else rounded
    if isinstance(value, bool) or value is None or isinstance(value, (int, str)):
        return value
    if isinstance(value, datetime):
        if value.tzinfo is not None:
            value = value.astimezone(timezone.utc).replace(tzinfo=None)
        return value.isoformat()
    if isinstance(value, date):
        return value.isoformat()
    if isinstance(value, bytes):
        return value.decode("utf-8", errors="replace")
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_value(item) for item in value]
    return value


def _sort_key(value: Any) -> tuple[int, Any]:
    if value is None:
        return (2, 0)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return (0, value)
    return (1, str(value))


def similarity(metric: str, distance: float) -> float:
    """Canonical similarity of LanceDB's _distance: l2 is the squared Euclidean distance, cosine is 1 - cos,
    dot is 1 - x.y, hamming counts differing bits."""
    if metric == "l2":
        return -math.sqrt(max(distance, 0.0))
    if metric == "hamming":
        return -distance
    return 1.0 - distance


def _within(score: float, score_min: float | None, score_max: float | None) -> bool:
    return (score_min is None or score >= score_min - 1e-9) and (score_max is None or score <= score_max + 1e-9)


def _columns(table: dict[str, Any], output: Sequence[str], vectors: bool | Sequence[str],
             order: Sequence[dict[str, Any]] | None = None, group: dict[str, Any] | None = None) -> list[str]:
    """Selected columns: the key, the output fields, requested vectors and the fields the sort clauses and the group key read."""
    columns = [table["key"], *[name for name in output if name != table["key"]]]
    if vectors is True:
        columns += [name for name in table.get("vectors", {}) if name not in columns]
    elif vectors:
        columns += [name for name in vectors if name not in columns]
    for clause in order or []:
        root = clause["key"].split(".")[0]
        if clause["key"] != "score" and root not in columns:
            columns.append(root)
    if group and group["key"].split(".")[0] not in columns:
        columns.append(group["key"].split(".")[0])
    return columns


def _shown(table: dict[str, Any], output: Sequence[str], vectors: bool | Sequence[str]) -> list[str]:
    return _columns(table, output, vectors)


def _record(table: dict[str, Any], row: dict[str, Any], columns: Sequence[str], score: float | None) -> dict[str, Any]:
    record: dict[str, Any] = {"id": _value(row[table["key"]])}
    if score is not None:
        record["score"] = _value(score)
    for name in columns:
        if name != table["key"]:
            record[name] = _value(row.get(name))
    return record


def _path(row: dict[str, Any], key: str) -> Any:
    value: Any = row
    for part in key.split("."):
        value = value.get(part) if isinstance(value, dict) else None
    return value


def _order(rows: list[Any], order: Sequence[dict[str, Any]] | None, value: Any) -> list[Any]:
    """Stable sorts by the sort clauses, last clause first; nulls last in both directions."""
    for clause in reversed(order or []):
        descending = clause.get("direction") == "desc"
        present = [item for item in rows if value(item, clause["key"]) is not None]
        missing = [item for item in rows if value(item, clause["key"]) is None]
        present.sort(key=lambda item: _sort_key(_value(value(item, clause["key"]))), reverse=descending)
        rows = present + missing
    return rows


def _page(table: dict[str, Any], hits: list[tuple[dict[str, Any], float]], shown: Sequence[str], limit: int,
          offset: int | None, score_min: float | None, score_max: float | None,
          order: Sequence[dict[str, Any]] | None, group: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """Ranked hits within the bounds, the window of offset + limit, sorted by the clauses, then paged; grouped hits when the
    search groups them."""
    if group:
        return _groups(table, hits, shown, limit, offset, score_min, score_max, group)
    window = [hit for hit in hits if _within(hit[1], score_min, score_max)][:(offset or 0) + limit]
    window = _order(window, order, lambda hit, key: hit[1] if key == "score" else _path(hit[0], key))
    return [_record(table, row, shown, score) for row, score in window[offset or 0:]]


def _groups(table: dict[str, Any], hits: list[tuple[dict[str, Any], float]], shown: Sequence[str], limit: int,
            offset: int | None, score_min: float | None, score_max: float | None, group: dict[str, Any]) -> list[dict[str, Any]]:
    """Hits grouped by the value of the group key: the groups whose best hit ranks highest (offset and limit count groups),
    each with its best `size` hits within the score bounds; a group left without a hit is dropped."""
    members: dict[str, list[tuple[dict[str, Any], float]]] = {}
    for row, score in hits:
        members.setdefault(json.dumps(_value(_path(row, group["key"]))), []).append((row, score))
    result = []
    for key in list(members)[offset or 0:(offset or 0) + limit]:
        kept = [(row, score) for row, score in members[key][:int(group.get("size", 1))] if _within(score, score_min, score_max)]
        if kept:
            result.append({"group": _value(_path(kept[0][0], group["key"])),
                           "hits": [_record(table, row, shown, score) for row, score in kept]})
    return result


def _window(client: Client, table: dict[str, Any], where: str | None, limit: int, offset: int | None,
            group: dict[str, Any] | None, version: Any) -> int:
    """Candidates a search ranks: limit plus offset, or every row the where string selects when the hits are grouped."""
    if group:
        return max(count(client, table, where, version), 1)
    return limit + (offset or 0)


def pack(bits: Sequence[Any]) -> list[int]:
    """A binary vector of 0 and 1 values packed into bytes, most significant bit first (numpy.packbits order)."""
    result = []
    for start in range(0, len(bits), 8):
        byte = 0
        for bit in bits[start:start + 8]:
            byte = (byte << 1) | (1 if bit else 0)
        result.append(byte << (8 - len(bits[start:start + 8])))
    return result


def _vector_query(handle: Any, plan: dict[str, Any], vector: Any, limit: int) -> Any:
    if plan.get("bits"):
        vector = np.array(pack(vector), dtype=np.uint8)
    query = handle.search(vector, vector_column_name=plan["column"]).distance_type(plan["metric"]).limit(limit)
    if plan.get("where"):
        query = query.where(plan["where"], prefilter=plan.get("prefilter", True))
    if plan.get("exact"):
        query = query.bypass_vector_index()
    if "nprobes" in plan:
        query = query.nprobes(int(plan["nprobes"]))
    if "refine_factor" in plan:
        query = query.refine_factor(int(plan["refine_factor"]))
    if "ef" in plan:
        query = query.ef(int(plan["ef"]))
    return query


def _nearest(client: Client, table: dict[str, Any], plan: dict[str, Any], vector: Any, limit: int,
             columns: Sequence[str], version: Any = None) -> list[tuple[dict[str, Any], float, float]]:
    """Rows nearest to a vector with their canonical similarity and LanceDB distance, best first, ties by key. A multivector
    distance is the number of query vectors minus the sum of their best cosine similarities (max_sim)."""
    handle = _read(client, table, version)
    rows = _vector_query(handle, plan, vector, limit).select(list(columns)).to_list()
    if plan.get("multivector"):
        scored = [(row, len(vector) - row["_distance"], row["_distance"]) for row in rows]
    else:
        scored = [(row, similarity(plan["metric"], row["_distance"]), row["_distance"]) for row in rows]
    scored.sort(key=lambda hit: (-hit[1], _sort_key(hit[0][table["key"]])))
    return scored


def vector_search(client: Client, table: dict[str, Any], plan: dict[str, Any], vector: Any, limit: int,
                  output: Sequence[str], offset: int | None = None, score_min: float | None = None,
                  score_max: float | None = None, native: bool = False, vectors: bool | Sequence[str] = False,
                  order: Sequence[dict[str, Any]] | None = None, version: Any = None,
                  group: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """Nearest neighbours ranked by canonical similarity (or LanceDB's distance with 'score native')."""
    columns = _columns(table, output, vectors, order, group)
    hits = _nearest(client, table, plan, vector, _window(client, table, plan.get("where"), limit, offset, group, version), columns, version)
    if native:
        ranked = [(row, distance) for row, _, distance in hits]
    else:
        ranked = [(row, score) for row, score, _ in hits]
    return _page(table, ranked, _shown(table, output, vectors), limit, offset, score_min, score_max, order, group)


def lookup_vector(client: Client, table: dict[str, Any], column: str, id: Any) -> Any:
    rows = client.table(table).search().where(_key_list(table, [id])).select([column]).limit(1).to_list()
    if not rows:
        raise KeyError(f"record {id!r} not found in {table['name']}")
    return rows[0][column]


def _text_query(plan: dict[str, Any], text: str) -> Any:
    columns = plan["columns"]
    operator = FullTextOperator.AND if plan.get("operator") == "and" else FullTextOperator.OR
    if plan.get("kind") == "phrase":
        if len(columns) != 1:
            unsupported("lancedb", "a phrase query over several fields")
        return PhraseQuery(text, columns[0], slop=int(plan.get("slop", 0)))
    fuzziness = int(plan.get("fuzziness", 0))
    if len(columns) == 1:
        return MatchQuery(text, columns[0], boost=float(plan.get("boosts", {}).get(columns[0], 1.0)), fuzziness=fuzziness,
                          operator=operator)
    boosts = [float(plan.get("boosts", {}).get(column, 1.0)) for column in columns]
    return MultiMatchQuery(text, list(columns), boosts=boosts, operator=operator)


def _matches(client: Client, table: dict[str, Any], plan: dict[str, Any], text: str, limit: int,
             columns: Sequence[str], version: Any = None) -> list[tuple[dict[str, Any], float]]:
    """Rows matching a full-text query with their BM25 _score, best first, ties by key."""
    handle = _read(client, table, version)
    query = handle.search(_text_query(plan, text), query_type="fts").limit(limit)
    if plan.get("where"):
        query = query.where(plan["where"], prefilter=plan.get("prefilter", True))
    rows = query.select(list(columns)).to_list()
    scored = [(row, float(row["_score"])) for row in rows]
    scored.sort(key=lambda hit: (-hit[1], _sort_key(hit[0][table["key"]])))
    return scored


def keyword_search(client: Client, table: dict[str, Any], plan: dict[str, Any], text: str, limit: int,
                   output: Sequence[str], offset: int | None = None, score_min: float | None = None,
                   score_max: float | None = None, vectors: bool | Sequence[str] = False,
                   order: Sequence[dict[str, Any]] | None = None, version: Any = None,
                   group: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    columns = _columns(table, output, vectors, order, group)
    hits = _matches(client, table, plan, text, _window(client, table, plan.get("where"), limit, offset, group, version), columns, version)
    return _page(table, hits, _shown(table, output, vectors), limit, offset, score_min, score_max, order, group)


def _contribution(fusion: str, k: int, weight: float, ranked: list[tuple[Any, float]]) -> dict[Any, float]:
    """Contribution of one leg: 1/(k + rank), weight * similarity, or weight * min-max normalized score."""
    if fusion == "rrf":
        return {key: 1.0 / (k + rank) for rank, (key, _) in enumerate(ranked, start=1)}
    if fusion == "weighted":
        return {key: weight * score for key, score in ranked}
    low = min((score for _, score in ranked), default=0.0)
    high = max((score for _, score in ranked), default=0.0)
    return {key: weight * ((score - low) / (high - low) if high > low else 1.0) for key, score in ranked}


def hybrid_search(client: Client, table: dict[str, Any], legs: Sequence[dict[str, Any]], limit: int, fusion: str,
                  output: Sequence[str], k: int = 60, offset: int | None = None, score_min: float | None = None,
                  score_max: float | None = None, vectors: bool | Sequence[str] = False,
                  order: Sequence[dict[str, Any]] | None = None, version: Any = None,
                  group: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """Runs every leg on its own and fuses in the runtime exactly as vecDSL defines rrf, weighted and relative_score."""
    columns = _columns(table, output, vectors, order, group)
    totals: dict[str, float] = {}
    rows: dict[str, dict[str, Any]] = {}
    for leg in legs:
        window = int(leg.get("limit", limit + (offset or 0)))
        if leg["kind"] == "vector":
            hits = [(row, score) for row, score, _ in _nearest(client, table, leg, leg["vector"], window, columns, version)]
        else:
            hits = _matches(client, table, leg, leg["text"], window, columns, version)
        ranked = []
        for row, score in hits:
            if _within(score, leg.get("score_min"), leg.get("score_max")):
                key = json.dumps(_value(row[table["key"]]))
                rows.setdefault(key, row)
                ranked.append((key, score))
        for key, part in _contribution(fusion, k, float(leg.get("weight", 1.0)), ranked).items():
            totals[key] = totals.get(key, 0.0) + part
    ranking = sorted(totals, key=lambda key: (-totals[key], _sort_key(_value(rows[key][table["key"]]))))
    return _page(table, [(rows[key], totals[key]) for key in ranking], _shown(table, output, vectors), limit, offset,
                 score_min, score_max, order, group)


def recommend(client: Client, table: dict[str, Any], plan: dict[str, Any], positives: Sequence[Any], limit: int,
              output: Sequence[str], negatives: Sequence[Any] = (), lookup: dict[str, Any] | None = None,
              offset: int | None = None, score_min: float | None = None, score_max: float | None = None,
              native: bool = False, vectors: bool | Sequence[str] = False, order: Sequence[dict[str, Any]] | None = None,
              version: Any = None, group: dict[str, Any] | None = None) -> list[dict[str, Any]]:
    """Searches from 2 * mean(positives) - mean(negatives) (mean(positives) without negatives); example ids are left out."""
    source = lookup or table
    def resolve(item: Any) -> list[float]:
        if isinstance(item, (list, tuple)):
            return [float(x) for x in item]
        return [float(x) for x in lookup_vector(client, source, plan["column"], item)]
    positive = [resolve(item) for item in positives]
    negative = [resolve(item) for item in negatives]
    mean_positive = [sum(values) / len(positive) for values in zip(*positive)]
    if negative:
        mean_negative = [sum(values) / len(negative) for values in zip(*negative)]
        query = [2 * p - n for p, n in zip(mean_positive, mean_negative)]
    else:
        query = mean_positive
    examples = set()
    if lookup is None:
        examples = {json.dumps(_value(_key(item))) for item in [*positives, *negatives] if not isinstance(item, (list, tuple))}
    columns = _columns(table, output, vectors, order, group)
    window = _window(client, table, plan.get("where"), limit, offset, group, version) + len(examples)
    hits = _nearest(client, table, plan, query, window, columns, version)
    kept = [hit for hit in hits if json.dumps(_value(hit[0][table["key"]])) not in examples]
    ranked = [(row, distance if native else score) for row, score, distance in kept]
    return _page(table, ranked, _shown(table, output, vectors), limit, offset, score_min, score_max, order, group)


def get_rows(client: Client, table: dict[str, Any], ids: Sequence[Any], output: Sequence[str],
             vectors: bool | Sequence[str] = False, where: str | None = None, version: Any = None) -> list[dict[str, Any]]:
    """Records by key, in the order of the ids; missing keys are left out."""
    if not ids:
        return []
    columns = _columns(table, output, vectors)
    condition = _key_list(table, ids) + (f" AND ({where})" if where else "")
    rows = _read(client, table, version).search().where(condition).select(columns).limit(len(ids)).to_list()
    found = {json.dumps(_value(row[table["key"]])): row for row in rows}
    ordered = [found[json.dumps(_value(_key(key)))] for key in ids if json.dumps(_value(_key(key))) in found]
    return [_record(table, row, columns, None) for row in ordered]


def count(client: Client, table: dict[str, Any], where: str | None = None, version: Any = None) -> int:
    return _read(client, table, version).count_rows(where)


def scroll(client: Client, table: dict[str, Any], output: Sequence[str], limit: int | None = None,
           offset: int | None = None, where: str | None = None, order: Sequence[dict[str, Any]] | None = None,
           vectors: bool | Sequence[str] = False, slice: dict[str, int] | None = None,
           version: Any = None) -> list[dict[str, Any]]:
    """Rows in key order (or the sort clauses, then the key), paged by offset and limit after the order is applied."""
    columns = _columns(table, output, vectors, order)
    query = _read(client, table, version).search()
    if where:
        query = query.where(where)
    rows = query.select(columns).limit(None).to_list()
    rows.sort(key=lambda row: _sort_key(_value(row[table["key"]])))
    rows = _order(rows, order, _path)
    if slice is not None:
        rows = [row for row in rows if _bucket(row[table["key"]], int(slice["total"])) == int(slice["index"])]
    start = offset or 0
    rows = rows[start:] if limit is None else rows[start:start + limit]
    shown = _shown(table, output, vectors)
    return [_record(table, row, shown, None) for row in rows]


def _bucket(key: Any, total: int) -> int:
    """A slice of the key space: the key's text hashed with FNV-1a 32, modulo the slice count (the same in every runtime)."""
    value = 0x811C9DC5
    for byte in json.dumps(_value(key)).encode("utf-8"):
        value = ((value ^ byte) * 0x01000193) & 0xFFFFFFFF
    return value % total


def sample(client: Client, table: dict[str, Any], size: int, output: Sequence[str], where: str | None = None,
           first: bool = False, version: Any = None) -> list[dict[str, Any]]:
    """A random sample of the matching records (first: the first records in key order)."""
    columns = _columns(table, output, False)
    query = _read(client, table, version).search()
    if where:
        query = query.where(where)
    rows = query.select(columns).limit(None).to_list()
    rows.sort(key=lambda row: _sort_key(_value(row[table["key"]])))
    chosen = rows[:size] if first else random.sample(rows, min(size, len(rows)))
    return [_record(table, row, columns, None) for row in chosen]


def distance_matrix(client: Client, table: dict[str, Any], plan: dict[str, Any], sample: int = 10, limit: int = 3,
                    where: str | None = None, version: Any = None) -> list[dict[str, Any]]:
    """A random sample with, for each sampled record, its nearest neighbours among the sample (canonical similarity)."""
    query = _read(client, table, version).search()
    if where:
        query = query.where(where)
    rows = query.select([table["key"], plan["column"]]).limit(None).to_list()
    chosen = random.sample(rows, min(sample, len(rows)))
    result = []
    for row in chosen:
        others = [(other, _similarity(plan["metric"], row[plan["column"]], other[plan["column"]]))
                  for other in chosen if other is not row]
        others.sort(key=lambda hit: (-hit[1], _sort_key(hit[0][table["key"]])))
        result.append({"id": _value(row[table["key"]]),
                       "neighbours": [{"id": _value(other[table["key"]]), "score": _value(score)} for other, score in others[:limit]]})
    return sorted(result, key=lambda item: _sort_key(item["id"]))


def _similarity(metric: str, x: Sequence[float], y: Sequence[float]) -> float:
    if metric == "cosine":
        norm = math.sqrt(sum(a * a for a in x)) * math.sqrt(sum(b * b for b in y))
        return sum(a * b for a, b in zip(x, y)) / norm if norm else 0.0
    if metric == "dot":
        return sum(a * b for a, b in zip(x, y))
    if metric == "hamming":
        return -float(sum(1 for a, b in zip(x, y) if a != b))
    return -math.sqrt(sum((a - b) ** 2 for a, b in zip(x, y)))


def list_versions(client: Client, table: dict[str, Any]) -> list[int]:
    return [entry["version"] for entry in client.table(table).list_versions()]
